#!/usr/bin/env python3
"""The Passport Page of a Country That Isn't There — runtime entry.

Standard library ONLY: the grader's pinned python3.13 image ships no
Pillow and no system fonts, so this program does not draw at runtime.
It embeds, as base64 below, the exact PNG bytes rendered by
`render.py` — the original PIL drawing program, kept in this repo as
provenance — and writes those bytes unchanged.

Output: $MAKEFUN_OUTPUT_DIR/entry.png, else /output/entry.png.
The image is one open passport spread of the Republic of Vessalia:
1024x720 PNG, 186,813 bytes, sha256
6157789d4aa56d8b6944b764286a35560f263a7957ab27e0025fdd2720d569ed.
"""

import base64
import os

_PNG_B64 = """

























































































































































































































































AAAoAAAAAAAAAAUAAAAAAACgAAAAAAAAABQAAAAAAACAAgAAAAAAYKr5/0X2pJGeBzrtAAAAAElFTkSuQmCC
"""

import base64
import os


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR") or "/output"
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(_PNG_B64)
    with open(os.path.join(out_dir, "entry.png"), "wb") as fh:
        fh.write(data)


if __name__ == "__main__":
    main()
